// HarnessCallbackServiceServer is the server API for HarnessCallbackService service.
// All implementations must embed UnimplementedHarnessCallbackServiceServer
// for forward compatibility.
//
// HarnessCallbackService provides the harness interface for agents executing in standalone mode.
// The SDK's CallbackHarness forwards all harness operations to the orchestrator via this service.
type HarnessCallbackServiceServer interface {
	// LLM Operations
	LLMComplete(context.Context, *LLMCompleteRequest) (*LLMCompleteResponse, error)
	LLMCompleteWithTools(context.Context, *LLMCompleteWithToolsRequest) (*LLMCompleteWithToolsResponse, error)
	LLMCompleteStructured(context.Context, *LLMCompleteStructuredRequest) (*LLMCompleteStructuredResponse, error)
	LLMStream(*LLMStreamRequest, grpc.ServerStreamingServer[LLMStreamResponse]) error
	// Tool Operations
	CallToolProto(context.Context, *CallToolProtoRequest) (*CallToolProtoResponse, error)
	CallToolProtoStream(*CallToolProtoStreamRequest, grpc.ServerStreamingServer[CallToolProtoStreamResponse]) error
	ListTools(context.Context, *ListToolsRequest) (*ListToolsResponse, error)
	// SearchTools returns a small, ranked, authz-filtered set of tools matching
	// a query — the meta-tool surface agents use instead of receiving every tool
	// (ADR-0047 facet 5). Per-tool authorization is enforced inside the handler;
	// this RPC-level gate only checks that the caller may use the harness.
	SearchTools(context.Context, *SearchToolsRequest) (*SearchToolsResponse, error)
	// Tool Work Queue Operations
	QueueToolWork(context.Context, *QueueToolWorkRequest) (*QueueToolWorkResponse, error)
	ToolResults(*ToolResultsRequest, grpc.ServerStreamingServer[ToolResultsResponse]) error
	// Plugin Operations
	QueryPlugin(context.Context, *QueryPluginRequest) (*QueryPluginResponse, error)
	ListPlugins(context.Context, *ListPluginsRequest) (*ListPluginsResponse, error)
	// Agent Operations
	DelegateToAgent(context.Context, *DelegateToAgentRequest) (*DelegateToAgentResponse, error)
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// Finding Operations
	SubmitFinding(context.Context, *SubmitFindingRequest) (*SubmitFindingResponse, error)
	// Observe emits a typed observation into the World (ADR-0007). The brain
	// resolves identity and topology; scope is derived server-side from context.
	Observe(context.Context, *ObserveRequest) (*ObserveResponse, error)
	// WorldView returns the caller's server-projected slice of the tenant World
	// (ADR-0012, sdk#341's read half). It is the counterpart to Observe: Observe
	// is the agent's only write, WorldView its only read.
	//
	// The slice is projected by the daemon from the mission record it created —
	// the tenant that owns the World and the scope that bounds the slice are read
	// there, never from this request. WorldViewRequest carries no tenant field and
	// no scope field, so an agent cannot name another tenant's World or a wider
	// slice: both are unrepresentable rather than rejected.
	WorldView(context.Context, *WorldViewRequest) (*WorldViewResponse, error)
	// Knowledge Operations
	//
	// The knowledge-graph READ surface. It exists on ComponentService too, and
	// that duplication is deliberate: without it here, a dispatched run holding
	// only its task-scoped callback grant cannot read the tenant graph, and the
	// agent would have to keep a component-scoped grant alive purely to call
	// recall — which defeats the point of scoping the dispatch at all.
	// See zerocool-plugins ADR-0006 and docs/adr/0001-callback-knowledge-reads.md.
	//
	// Read-only by construction. The write half is NOT mirrored: the projector
	// is the sole graph writer (ADR-0012), and sdk#451 already removed the
	// generic graph-write RPC from ComponentService.
	QueryNodes(context.Context, *QueryNodesRequest) (*QueryNodesResponse, error)
	FindSimilarAttacks(context.Context, *FindSimilarAttacksRequest) (*FindSimilarAttacksResponse, error)
	GetAttackChains(context.Context, *GetAttackChainsRequest) (*GetAttackChainsResponse, error)
	FindSimilarFindings(context.Context, *FindSimilarFindingsRequest) (*FindSimilarFindingsResponse, error)
	GetRelatedFindings(context.Context, *GetRelatedFindingsRequest) (*GetRelatedFindingsResponse, error)
	GetFindings(context.Context, *GetFindingsRequest) (*GetFindingsResponse, error)
	// ApplicationFindings answers the one lifecycle question the reads above
	// cannot: for this Application, what is still open, and does anything
	// actually run the code it is in (gibson#1669).
	//
	// The reads above are hybrid vector-and-graph SEARCH — text or embedding, a
	// node-type filter, top-k. Reachability is a TRAVERSAL: is this Package
	// inside an Image that a Deployment of this Application runs, and does that
	// Deployment expose a Host. No top-k over a node-type filter answers it.
	//
	// It is one bounded question rather than a Cypher surface, deliberately: an
	// agent able to send arbitrary Cypher would be a second unaudited path into
	// the tenant graph, and the traversal an agent needs is knowable in advance.
	ApplicationFindings(context.Context, *ApplicationFindingsRequest) (*ApplicationFindingsResponse, error)
	GetRunFindings(context.Context, *GetRunFindingsRequest) (*GetRunFindingsResponse, error)
	GetMissionRunHistory(context.Context, *GetMissionRunHistoryRequest) (*GetMissionRunHistoryResponse, error)
	// Planning Operations
	GetPlanContext(context.Context, *GetPlanContextRequest) (*GetPlanContextResponse, error)
	ReportStepHints(context.Context, *ReportStepHintsRequest) (*ReportStepHintsResponse, error)
	// Distributed Tracing Operations
	RecordSpan(context.Context, *RecordSpanRequest) (*RecordSpanResponse, error)
	RecordSpans(context.Context, *RecordSpansRequest) (*RecordSpansResponse, error)
	// Credential Operations
	GetCredential(context.Context, *GetCredentialRequest) (*GetCredentialResponse, error)
	// Taxonomy Operations
	GetTaxonomySchema(context.Context, *GetTaxonomySchemaRequest) (*GetTaxonomySchemaResponse, error)
	GenerateNodeID(context.Context, *GenerateNodeIDRequest) (*GenerateNodeIDResponse, error)
	ValidateFinding(context.Context, *ValidateFindingRequest) (*ValidateFindingResponse, error)
	ValidateGraphNode(context.Context, *ValidateGraphNodeRequest) (*ValidateGraphNodeResponse, error)
	ValidateRelationship(context.Context, *ValidateRelationshipRequest) (*ValidateRelationshipResponse, error)
	// Mission Management Operations
	// These enable agents to autonomously create, run, and manage missions
	CreateMission(context.Context, *CreateMissionRequest) (*CreateMissionResponse, error)
	RunMission(context.Context, *RunMissionRequest) (*RunMissionResponse, error)
	GetMissionStatus(context.Context, *GetMissionStatusRequest) (*GetMissionStatusResponse, error)
	WaitForMission(context.Context, *WaitForMissionRequest) (*WaitForMissionResponse, error)
	ListMissions(context.Context, *ListMissionsRequest) (*ListMissionsResponse, error)
	CancelMission(context.Context, *CancelMissionRequest) (*CancelMissionResponse, error)
	GetMissionResults(context.Context, *GetMissionResultsRequest) (*GetMissionResultsResponse, error)
	// Authorization Operations
	// Authorize checks whether the calling component's current work execution
	// is permitted to perform action on resource. The daemon resolves the
	// run_id to a (user_id, tenant_id) pair and consults FGA.
	Authorize(context.Context, *AuthorizeRequest) (*AuthorizeResponse, error)
	// WorkspaceList returns metadata for every workspace configured for
	// the calling component's active mission. Returns an empty list when
	// the mission has no workspaces.
	WorkspaceList(context.Context, *WorkspaceListRequest) (*WorkspaceListResponse, error)
	// WorkspaceGetInfo returns name + path for a single workspace. An empty
	// name resolves to the mission's primary workspace (single-repo case).
	// Returns NOT_FOUND when no workspace with that name exists.
	WorkspaceGetInfo(context.Context, *WorkspaceGetInfoRequest) (*WorkspaceGetInfoResponse, error)
	// WorkspaceReadFile reads a file from the named workspace. Path is
	// relative to the workspace root. Files larger than 16 MB return
	// RESOURCE_EXHAUSTED; a streaming variant is deferred to a follow-on
	// spec.
	WorkspaceReadFile(context.Context, *WorkspaceReadFileRequest) (*WorkspaceReadFileResponse, error)
	// WorkspaceWriteFile writes content to a file in the named workspace.
	// Path is relative to the workspace root. Content larger than 16 MB
	// returns RESOURCE_EXHAUSTED; a streaming variant is deferred.
	WorkspaceWriteFile(context.Context, *WorkspaceWriteFileRequest) (*WorkspaceWriteFileResponse, error)
	// WorkspaceListFiles returns paths matching the given glob pattern,
	// relative to the workspace root. Result sets larger than 10,000 paths
	// are truncated to the first 10,000 with truncated=true on the
	// response.
	WorkspaceListFiles(context.Context, *WorkspaceListFilesRequest) (*WorkspaceListFilesResponse, error)
	// WorkspaceCommit stages all changes in the workspace and creates a
	// commit with the given message. Returns the commit SHA.
	WorkspaceCommit(context.Context, *WorkspaceCommitRequest) (*WorkspaceCommitResponse, error)
	// WorkspacePush pushes committed changes to the remote configured for
	// the workspace. Returns PERMISSION_DENIED on auth failure against
	// the remote.
	WorkspacePush(context.Context, *WorkspacePushRequest) (*WorkspacePushResponse, error)
	// DevboxExec runs one command in the caller's session Devbox — a
	// session-lifetime sandbox resolved (and lazily created on first call)
	// by (tenant, session_id), then REUSED across calls in that session.
	// This is deliberately distinct from the per-call SANDBOXED tool path
	// (CallToolProto), which stays one microVM per call; a Devbox holds
	// working state (checkouts, build caches) that per-call isolation would
	// throw away between commands.
	DevboxExec(*DevboxExecRequest, grpc.ServerStreamingServer[DevboxExecResponse]) error
	// Session-context store: an opaque, versioned blob per (tenant,
	// session_id), persisted in the per-tenant dataplane store. The daemon
	// never interprets the bytes — the component owns its own format. This
	// is the TRUSTED home for a session's local context; it must never be
	// written to the untrusted Devbox volume (that invariant is the
	// client's to keep, but this store is why keeping it costs nothing).
	// Writes are guarded by an etag (If-Match) so concurrent writers cannot
	// clobber each other; the server enforces a TTL and a size cap.
	PutSessionContext(context.Context, *PutSessionContextRequest) (*PutSessionContextResponse, error)
	GetSessionContext(context.Context, *GetSessionContextRequest) (*GetSessionContextResponse, error)
	DeleteSessionContext(context.Context, *DeleteSessionContextRequest) (*DeleteSessionContextResponse, error)
	// SubscribeInput streams the inputs for the calling member, in order,
	// across every job it holds. Each Input carries the per-turn grant the
	// member uses for every tool call of that turn. The stream stays open
	// for the life of the member.
	SubscribeInput(*SubscribeInputRequest, grpc.ServerStreamingServer[SubscribeInputResponse]) error
	// PullJob returns the next queued job of the calling member's bank, or
	// nothing when the queue is empty. A member with a free slot calls it
	// after each heartbeat. The daemon assigns the job to the member.
	PullJob(context.Context, *PullJobRequest) (*PullJobResponse, error)
	// ReportJobState tells the daemon a job moved to WORKING or WAITING, and
	// names the Claude Code session that holds it so a restart can resume
	// it. A member never reports CLOSED: a scorer closes the job.
	ReportJobState(context.Context, *ReportJobStateRequest) (*ReportJobStateResponse, error)
	// ReportDeliverable records one outward result the driver performed at
	// wrap-up: a pushed branch or an opened merge request.
	ReportDeliverable(context.Context, *ReportDeliverableRequest) (*ReportDeliverableResponse, error)
	// OpenJob opens a job on a bank from a dispatched agent, under its
	// grant. It mirrors gibson.job.v1.JobService.OpenJob.
	OpenJob(context.Context, *OpenJobRequest) (*OpenJobResponse, error)
	// SendInput sends the next message to an open job from a dispatched
	// agent, under its grant. It mirrors gibson.job.v1.JobService.SendInput.
	SendInput(context.Context, *SendInputRequest) (*SendInputResponse, error)
	// CloseJob closes a job with a verdict and a score from a dispatched
	// agent, under its grant. A verification agent is the usual caller. It
	// mirrors gibson.job.v1.JobService.CloseJob.
	CloseJob(context.Context, *CloseJobRequest) (*CloseJobResponse, error)
	mustEmbedUnimplementedHarnessCallbackServiceServer()
}

